package cn.xinji.agentplatform.enforcement.penalty;

import static org.junit.jupiter.api.Assertions.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/** Controlled project-score C only; not real legal standards, authorization or product I. */
class PenaltyPublishChecksTest {
    private final PenaltyFormula.Expression formula=new PenaltyFormula.Binary(PenaltyFormula.Operator.MULTIPLY,new PenaltyFormula.Input("B"),new PenaltyFormula.Constant(new BigDecimal("2"),"PROJECT-FACTOR@1"));
    private final PenaltyFormula.Semantics semantics=new PenaltyFormula.Semantics("PROJECT_SCORE","NONE","POINT",2,RoundingMode.HALF_UP);
    private final PenaltyFormula.Range range=new PenaltyFormula.Range(BigDecimal.ZERO,new BigDecimal("100"),"PROJECT-LEGAL",1);
    private List<PenaltyPublishChecks.Boundary> boundaries(){return List.of(boundary("LOWER","0","0"),boundary("UPPER","50","100"));}
    private PenaltyPublishChecks.Boundary boundary(String name,String amount,String expected){return new PenaltyPublishChecks.Boundary(name,Map.of("B",new PenaltyFormula.Amount(new BigDecimal(amount),true,"PROJECT-CONTROLLED","1",name)),new BigDecimal(expected));}
    private PenaltyPublishChecks.Input input(boolean applicable,PenaltyFormula.Semantics amount,List<PenaltyPublishChecks.Boundary> samples,List<PenaltyPublishChecks.Overlap> overlaps){return new PenaltyPublishChecks.Input("PROJECT-ORG",applicable,"PROJECT-LEGAL",1,formula,amount,range,samples,overlaps);}
    private PenaltyPublishChecks checks(String state){return new PenaltyPublishChecks(new PenaltyPublishChecks.Inputs(){public void assertCurrentAccess(String actor,PenaltyPublishChecks.Input input){}public PenaltyPublishChecks.Basis legalBasis(String actor,String org,String ref,long revision){return new PenaltyPublishChecks.Basis(ref,revision,state,"ACTIVE",List.of());}});}
    @Test void exactReviewedProjectInputHasReproducibleLowerAndUpperTrials(){var result=checks("CONFIRMED").validate("PROJECT-TEST",input(true,semantics,boundaries(),List.of()));assertTrue(result.publishable());assertEquals(2,result.trials().size());assertEquals(BigDecimal.ZERO.setScale(2),result.trials().getFirst().amount());assertEquals(new BigDecimal("100.00"),result.trials().getLast().amount());}
    @Test void unresolvedLegalBasisNeverPublishes(){var result=checks("PENDING").validate("PROJECT-TEST",input(true,semantics,boundaries(),List.of()));assertFalse(result.publishable());assertTrue(result.gaps().contains("LEGAL_REFERENCE_REVIEW_REQUIRED"));assertTrue(result.trials().isEmpty());}
    @Test void missingRoundingAndUnitDoNotDefault(){var missing=new PenaltyFormula.Semantics("PROJECT_SCORE","NONE","",2,null);var result=checks("CONFIRMED").validate("PROJECT-TEST",input(true,missing,boundaries(),List.of()));assertFalse(result.publishable());assertTrue(result.gaps().contains("AMOUNT_SEMANTICS_REQUIRED"));}
    @Test void inapplicableProcedureNeverCalculates(){var result=checks("CONFIRMED").validate("PROJECT-TEST",input(false,semantics,boundaries(),List.of()));assertFalse(result.publishable());assertTrue(result.trials().isEmpty());}
    @Test void overlapsWithoutPriorityAreNotResolvedByChoosingHeavier(){var result=checks("CONFIRMED").validate("PROJECT-TEST",input(true,semantics,boundaries(),List.of(new PenaltyPublishChecks.Overlap("PROJECT-OTHER",1,null))));assertFalse(result.publishable());assertTrue(result.gaps().contains("OVERLAP_PRIORITY_REQUIRED"));assertTrue(result.trials().isEmpty());}
    @Test void missingBoundaryAndWrongExpectedResultReject(){assertFalse(checks("CONFIRMED").validate("PROJECT-TEST",input(true,semantics,List.of(),List.of())).publishable());var result=checks("CONFIRMED").validate("PROJECT-TEST",input(true,semantics,List.of(boundary("LOWER","0","1"),boundary("UPPER","50","100")),List.of()));assertFalse(result.publishable());assertTrue(result.gaps().contains("BOUNDARY_TRIAL_MISMATCH"));}
    @Test void currentAccessRevocationBeforeReturnIsNotAValidPublication(){var revoked=new PenaltyPublishChecks(new PenaltyPublishChecks.Inputs(){int calls;public void assertCurrentAccess(String actor,PenaltyPublishChecks.Input input){if(++calls==2)throw new SecurityException("Controlled current withdrawal");}public PenaltyPublishChecks.Basis legalBasis(String actor,String org,String ref,long revision){return new PenaltyPublishChecks.Basis(ref,revision,"CONFIRMED","ACTIVE",List.of());}});assertThrows(SecurityException.class,()->revoked.validate("PROJECT-TEST",input(true,semantics,boundaries(),List.of())));}
    @Test void confirmedButStaleBindingOrRemainingGapsDoNotPublish(){for(var basis:List.of(new PenaltyPublishChecks.Basis("PROJECT-LEGAL",1,"CONFIRMED","NEEDS_REVIEW",List.of()),new PenaltyPublishChecks.Basis("PROJECT-LEGAL",1,"CONFIRMED","ACTIVE",List.of("SOURCE_UPDATED")))){var checks=new PenaltyPublishChecks(new PenaltyPublishChecks.Inputs(){public void assertCurrentAccess(String actor,PenaltyPublishChecks.Input input){}public PenaltyPublishChecks.Basis legalBasis(String actor,String org,String ref,long revision){return basis;}});assertFalse(checks.validate("PROJECT-TEST",input(true,semantics,boundaries(),List.of())).publishable());}}
    @Test void sourceUnavailableIsNotTurnedIntoMissingDataOrSuccess(){var unavailable=new PenaltyPublishChecks(new PenaltyPublishChecks.Inputs(){public void assertCurrentAccess(String actor,PenaltyPublishChecks.Input input){}public PenaltyPublishChecks.Basis legalBasis(String actor,String org,String ref,long revision){throw new IllegalStateException("Controlled source unavailable");}});assertThrows(IllegalStateException.class,()->unavailable.validate("PROJECT-TEST",input(true,semantics,boundaries(),List.of())));}
}
